Object.assign(CHECKS,{"l2": {"14": {"q": "Куда отец отправил Петра служить?", "o": ["В Оренбург", "В Петербург", "В Москву", "В Симбирск"], "ex": "«Ты едешь в Оренбург служить под его начальством»."}, "16": {"q": "Сколько Пётр проиграл Зурину на бильярде?", "o": ["Сто рублей", "Десять рублей", "Пятьдесят рублей", "Тысячу рублей"], "ex": "Зурин «объявил мне, что я проиграл сто рублей»."}}, "l4": {"8": {"q": "С чем Пётр сравнил езду кибитки по сугробам?", "o": ["С плаванием судна по бурному морю", "С ездой по горной дороге", "С полётом птицы", "С качанием колыбели"], "ex": "«Это похоже было на плавание судна по бурному морю»."}, "15": {"q": "Что попросил вожатый вместо чая?", "o": ["Стакан вина", "Квасу", "Ещё сахару", "Хлеба с солью"], "ex": "«Прикажите поднести стакан вина; чай не наше казацкое питье»."}}, "l7": {"3": {"q": "Из-за чего подрались Прохоров и Устинья Негулина?", "o": ["Из-за шайки горячей воды", "Из-за коровы", "Из-за дров", "Из-за денег"], "ex": "Прохоров «подрался в бане с Устиньей Негулиной за шайку горячей воды»."}, "7": {"q": "Какой описал Швабрин Машу?", "o": ["Совершенною дурочкою", "Гордой красавицей", "Строгой и умной", "Весёлой хохотушкой"], "ex": "«Швабрин описал мне Машу, капитанскую дочь, совершенною дурочкою»."}}, "l8": {"10": {"q": "Чьи стихи, по словам Швабрина, напоминает песенка Петра?", "o": ["Тредьяковского", "Ломоносова", "Державина", "Сумарокова"], "ex": "Стихи «достойны учителя моего, Василья Кирилыча Тредьяковского»."}, "28": {"q": "Где Пётр и Швабрин условились драться?", "o": ["За скирдами у крепости", "На берегу реки", "В доме коменданта", "У церкви"], "ex": "«Мы условились драться за скирдами, что находились подле крепости»."}, "46": {"q": "Кто на самом деле выведал всё о поединке?", "o": ["Василиса Егоровна", "Палашка", "Комендант", "Савельич"], "ex": "Иван Игнатьич: «Василиса Егоровна выведала все от меня»."}}, "l9": {"3": {"q": "О чём спросила Маша после признания Петра?", "o": ["Не будет ли препятствия со стороны его родных", "Когда будет свадьба", "Не уедет ли он в Петербург", "Любит ли он её на самом деле"], "ex": "«Со стороны твоих родных не будет ли препятствия?»"}, "8": {"q": "Отчего занемогла матушка Петра?", "o": ["Узнала о поединке и ране сына", "От простуды", "От тоски", "От ссоры с батюшкой"], "ex": "«Матушка твоя, узнав о твоем поединке и о том, что ты ранен, с горести занемогла»."}, "11": {"q": "Кого Савельич винит в ране Петра?", "o": ["Мусье, который учил его фехтовать", "Швабрина", "Самого себя", "Коменданта"], "ex": "«Не я, проклятый мусье всему виноват»."}}, "l10": {"10": {"q": "Как комендант выпроводил жену из дома?", "o": ["Сказал, что у отца Герасима тайные известия", "Послал её на рынок", "Отправил к генералу", "Сказал, что Маша заболела"], "ex": "Он сказал, «будто бы отец Герасим получил из Оренбурга какие-то чудные известия»."}, "21": {"q": "Почему во второй раз хитрость коменданта не удалась?", "o": ["Он повторил ту же выдумку", "Палашка проговорилась", "Жена подслушала у двери", "Маша всё рассказала"], "ex": "Иван Кузмич «не нашел другого способа, кроме как единожды уже им употребленного»."}, "34": {"q": "Царствование какого императора вспоминает рассказчик?", "o": ["Александра", "Петра", "Павла", "Николая"], "ex": "«…дожил я до кроткого царствования императора Александра»."}}, "l11": {"4": {"q": "Кто ехал на белом коне в красном кафтане?", "o": ["Пугачёв", "Швабрин", "Юлай", "Иван Игнатьич"], "ex": "«На белом коне ехал человек в красном кафтане… это был сам Пугачев»."}}, "l13": {"8": {"q": "Кем попадья назвала Машу перед злодеями?", "o": ["Своей больной племянницей", "Своей дочерью", "Служанкой", "Сиротой из Оренбурга"], "ex": "«А как сказала я про больную племянницу…»"}, "18": {"q": "В какую комнату ввели Петра к Пугачёву?", "o": ["Где накануне он прощался с Машей", "В кухню", "В казарму", "В церковь"], "ex": "Его ввели «в ту комнату, где накануне так нежно прощался я с Марьей Ивановною»."}}, "l15": {"21": {"q": "Что Пугачёв бросил в лицо Савельичу?", "o": ["Бумагу с его списком", "Заячий тулуп", "Шапку", "Кошелёк"], "ex": "Пугачёв выхватил «бумагу из рук секретаря» и бросил «ее в лицо Савельичу»."}}, "l16": {"4": {"q": "С кого начали собирать голоса на совете?", "o": ["С младших по чину", "Со старших по чину", "С генерала", "С купцов"], "ex": "«Начнем собирать голоса по законному порядку, то есть начиная с младших по чину»."}, "17": {"q": "Что было у мятежников под Оренбургом?", "o": ["Артиллерия из взятых крепостей", "Отряд гусар", "Обоз с хлебом", "Корабли"], "ex": "«При них была и артиллерия, взятая Пугачевым в малых крепостях»."}, "26": {"q": "Сколько дней Швабрин дал Маше на раздумье?", "o": ["Три дня", "Неделю", "Один день", "Месяц"], "ex": "«Он согласился ждать еще три дня»."}}, "l17": {"11": {"q": "Что стояло у ворот «дворца» Пугачёва?", "o": ["Винные бочки и две пушки", "Виселица", "Кибитка", "Стог сена"], "ex": "«У ворот стояло несколько винных бочек и две пушки»."}, "26": {"q": "Что, по словам старичка, творится в Оренбурге?", "o": ["Голод и мор", "Праздник", "Всего вдоволь", "Пожар"], "ex": "«Все беглецы согласно показывают, что в Оренбурге голод и мор»."}, "43": {"q": "О чём Савельич пообещал больше не упоминать?", "o": ["О заячьем тулупе", "О долге Зурину", "О письме отца", "О своей лошади"], "ex": "«…а о заячьем тулупе и упоминать уж не стану»."}}, "l18": {"25": {"q": "Что сделала Маша, поняв, кто перед ней?", "o": ["Закрыла лицо руками и упала без чувств", "Убежала", "Поблагодарила его", "Позвала Палашу"], "ex": "«Она закрыла лицо обеими руками и упала без чувств»."}, "40": {"q": "Через кого Маша держала связь с попадьёй?", "o": ["Через Палашку", "Через Савельича", "Через отца Герасима", "Через Максимыча"], "ex": "Маша «имела с нею всегдашние сношения через Палашку»."}}, "l19": {"20": {"q": "Что Зурин думает о женитьбе?", "o": ["Что женитьба — блажь", "Что это лучшее решение", "Что надо венчаться в Оренбурге", "Что надо спросить отца"], "ex": "«Поверь же ты мне, что женитьба блажь»."}, "32": {"q": "Кто разбил Пугачёва под крепостью Татищевой?", "o": ["Князь Голицын", "Зурин", "Андрей Карлович", "Пётр Гринёв"], "ex": "«Вскоре князь Голицын, под крепостию Татищевой, разбил Пугачева»."}}, "l20": {"12": {"q": "Чьё имя так и не прозвучало на суде?", "o": ["Марьи Ивановны", "Савельича", "Зурина", "Пугачёва"], "ex": "«Имя дочери белогорского коменданта не было произнесено в присутствии комиссии»."}, "19": {"q": "Что листал батюшка в тот вечер?", "o": ["Придворный календарь", "Библию", "Письмо сына", "Газету"], "ex": "Батюшка сидел, «перевертывая листы Придворного календаря»."}, "41": {"q": "Что сказала дама о прощении Гринёва?", "o": ["Императрица не может его простить", "Что поможет сразу же", "Что не станет читать письмо", "Что надо прийти завтра"], "ex": "«Императрица не может его простить»."}}});
Object.assign(SHORTTEXT,{"l1": {"paras": [{"t": "Отец мой Андрей Петрович Гринёв в молодости своей служил при графе Минихе и вышел в отставку [[премьер-майором|pm]] в 17.. году. С тех пор жил он в своей Симбирской деревне, где и женился на девице Авдотье Васильевне Ю., дочери бедного тамошнего дворянина. Нас было девять человек детей. Все мои братья и сёстры умерли во младенчестве."}, {"t": "Матушка была ещё мною брюхата, как уже я был записан в Семёновский полк сержантом, по милости майора гвардии князя Б., близкого нашего родственника. … Я считался в отпуску до окончания наук."}, {"t": "В то время воспитывались мы не по-нонешнему. С пятилетнего возраста отдан я был на руки [[стремянному|str]] Савельичу, за трезвое поведение пожалованному мне в [[дядьки|dyad]]. Под его надзором на двенадцатом году выучился я русской грамоте и мог очень здраво судить о свойствах борзого кобеля."}], "games": [{"type": "choice", "label": "Чья история", "q": "Кто воспитывал Петрушу с пяти лет?", "opts": ["Князь Б.", "Савельич", "Отец", "Матушка"], "a": 1, "para": 2, "ex": "С пяти лет Пётр был отдан на руки Савельичу."}, {"type": "choice", "label": "Детали", "q": "В какой полк Петрушу записали ещё до рождения?", "opts": ["Преображенский", "Измайловский", "Семёновский", "Оренбургский"], "a": 2, "para": 1, "ex": "Его записали сержантом в Семёновский полк."}, {"type": "choice", "label": "Словарь эпохи", "q": "Кем служил Савельич до того, как стал дядькой?", "opts": ["Стремянным", "Учителем", "Ямщиком", "Сержантом"], "a": 0, "para": 2, "ex": "Савельич был стремянным: сопровождал барина на охоте."}]}, "l2": {"paras": [{"t": "Однажды осенью матушка варила в гостиной медовое варенье, а я, облизываясь, смотрел на кипучие пенки. Батюшка у окна читал Придворный календарь, ежегодно им получаемый. …"}, {"note": "Батюшка решает, где служить сыну."}, {"t": "«Петруша в Петербург не поедет. Чему научится он, служа в Петербурге? мотать да повесничать? Нет, пускай послужит он в армии, да потянет лямку, да понюхает пороху, да будет солдат, а не [[шаматон|sham]]»."}, {"note": "Прощание у кибитки."}, {"t": "«Прощай, Пётр. Служи верно, кому присягнёшь; слушайся начальников; за их лаской не гоняйся; на службу не напрашивайся; от службы не отговаривайся; и помни пословицу: береги платье [[снову|snovu]], а честь смолоду»."}], "games": [{"type": "choice", "label": "Чья реплика", "q": "Кто сказал эти слова?", "quote": "«…береги платье снову, а честь смолоду»", "opts": ["Савельич", "Матушка", "Отец", "Князь Б."], "a": 2, "para": 4, "ex": "Это наказ отца при прощании."}, {"type": "error", "label": "Найди ошибку", "q": "В цитату вкралось одно неверное слово. Нажми на него.", "words": ["Нет,", "пускай", "послужит", "он", "в", "гвардии,", "да", "потянет", "лямку,", "да", "понюхает", "пороху"], "a": 5, "para": 2, "ex": "Отец сказал «в армии». В гвардию, то есть в Петербург, он сына как раз не пустил."}, {"type": "choice", "label": "Мотивы", "q": "Почему отец не пустил сына служить в Петербург?", "opts": ["Там шла война", "Боялся, что там сын научится лишь мотать да повесничать", "Так решила матушка", "Не хватило денег на дорогу"], "a": 1, "para": 2, "ex": "По словам отца, в Петербурге сын научится только «мотать да повесничать»."}]}, "l3": {"paras": [{"note": "Пётр с Савельичем едут в [[кибитке|kib]]. Ямщик заметил на краю неба облачко, но Пётр велел ехать дальше."}, {"t": "Ямщик поскакал; но всё поглядывал на восток. Лошади бежали дружно. Ветер между тем час от часу становился сильнее. Облачко обратилось в белую тучу, которая тяжело подымалась, росла и постепенно облегала небо."}, {"t": "Пошёл мелкий снег — и вдруг повалил хлопьями. Ветер завыл; сделалась метель. В одно мгновение тёмное небо смешалось со снежным морем. Всё исчезло. «Ну, барин, — закричал [[ямщик|yam]], — беда: [[буран|bur]]!»"}], "games": [{"type": "order", "label": "Хронология", "q": "Восстанови, как начинался буран.", "items": ["Ветер становится всё сильнее", "Облачко превращается в белую тучу", "Снег вдруг валит хлопьями", "Ямщик кричит: «беда: буран!»"], "para": 1, "ex": "Сначала ветер и туча, потом снег хлопьями — и только тогда крик ямщика."}, {"type": "choice", "label": "Детали", "q": "Куда всё время поглядывал ямщик?", "opts": ["На север", "На Савельича", "На восток", "На дорогу позади"], "a": 2, "para": 1, "ex": "Ямщик поскакал, но всё поглядывал на восток, откуда шла туча."}]}, "l4": {"paras": [{"t": "Вдруг увидел я что-то чёрное. «Эй, ямщик! — закричал я, — смотри: что там такое чернеется?» Ямщик стал всматриваться. «А бог знает, барин, — сказал он, садясь на своё место, — воз не воз, дерево не дерево, а кажется, что шевелится. Должно быть, или волк, или человек»."}, {"note": "Это был человек. Пётр спросил его, знает ли он эту сторону."}, {"t": "«Сторона мне знакомая, — отвечал дорожный, — слава богу, исхожена и изъезжена вдоль и поперёк. Да, вишь, какая погода: как раз собьёшься с дороги. Лучше здесь остановиться да переждать, авось буран утихнет да небо прояснится: тогда найдём дорогу по звёздам»."}, {"note": "Вскоре дорожный указал, куда ехать."}, {"t": "«А потому, что ветер оттоле потянул, — отвечал дорожный, — и я слышу, дымом пахнуло; знать, деревня близко»"}, {"note": "Дорожный вывел кибитку к постоялому двору. Здесь Пётр впервые разглядел своего вожатого."}, {"t": "Наружность его показалась мне замечательна: он был лет сорока, росту среднего, худощав и широкоплеч. В чёрной бороде его показывалась проседь; живые большие глаза так и бегали. Лицо его имело выражение довольно приятное, но плутовское. Волоса были обстрижены в кружок; на нём был оборванный армяк и татарские шаровары."}, {"note": "Постоялый двор стоял «в стороне, в степи, далече от всякого селения» и «очень походил на разбойническую пристань». Хозяин узнал вожатого и заговорил с ним странно."}, {"t": "«Эхе, — сказал он, — опять ты в нашем краю! Отколе бог принес?» Вожатый мой мигнул значительно и отвечал поговоркою: «В огород летал, конопли клевал; швырнула бабушка камушком — да мимо. Ну, а что ваши?» — Да что наши! — отвечал хозяин, продолжая иносказательный разговор. — Стали было к вечерне звонить, да попадья не велит: поп в гостях, черти на погосте. «Молчи, дядя, — возразил мой бродяга, — будет дождик, будут и грибки; а будут грибки, будет и кузов. А теперь (тут он мигнул опять) заткни топор за спину: лесничий ходит. Ваше благородие! за ваше здоровье!»"}, {"t": "Я ничего не мог тогда понять из этого воровского разговора; но после уж догадался, что дело шло о делах Яицкого войска, в то время только что усмиренного после бунта 1772 года."}], "games": [{"type": "choice", "label": "Детали", "q": "Что, по словам ямщика, чернелось в снегу?", "opts": ["Воз с сеном", "Сухое дерево", "Или волк, или человек", "Огни деревни"], "a": 2, "para": 0, "ex": "«Воз не воз, дерево не дерево… или волк, или человек»."}, {"type": "hero", "label": "Выбор героя", "q": "Буран, дороги не видно. Незнакомец уверен, что жильё близко. Как поступишь?", "opts": ["Довериться ему и ехать за ним", "Стоять на месте до утра", "Повернуть обратно"], "reveal": "В книге Пётр доверился дорожному: тот почуял дым, и кибитка двинулась к жилью. Эта встреча ещё изменит его судьбу."}, {"type": "choice", "label": "Детали", "q": "Как дорожный понял, что деревня близко?", "opts": ["Нашёл дорогу по звёздам", "Почуял запах дыма", "Услышал лай собак", "Увидел огни"], "a": 1, "para": 4, "ex": "«Я слышу, дымом пахнуло; знать, деревня близко». Звёзды он только предлагал ждать."}, {"type": "portrait", "label": "Словесный портрет", "q": "Вспомни, как выглядел вожатый, и собери его портрет по памяти.", "para": 6, "clauses": [["Наружность его показалась мне замечательна:", null], ["он был лет сорока,", "age"], ["росту среднего, худощав и широкоплеч.", "body"], ["В чёрной бороде его показывалась проседь;", "beard"], ["живые большие глаза так и бегали.", "eyes"], ["Лицо его имело выражение довольно приятное, но плутовское.", "smirk"], ["Волоса были обстрижены в кружок;", "hair"], ["на нём был оборванный армяк и татарские шаровары.", "coat"]]}]}, "l5": {"paras": [{"note": "Утром буран утих. Пётр захотел отблагодарить вожатого и велел Савельичу отдать ему свой заячий тулуп."}, {"t": "«Помилуй, батюшка Пётр Андреич! — сказал Савельич. — Зачем ему твой заячий тулуп? Он его пропьёт, собака, в первом [[кабаке|kabak]]»."}, {"note": "Пётр настоял на своём."}, {"t": "Бродяга тут же стал его примеривать. В самом деле тулуп, из которого успел и я вырасти, был немножко для него узок. Однако он кое-как умудрился и надел его, распоров по швам."}, {"t": "Бродяга был чрезвычайно доволен моим подарком. Он проводил меня до кибитки и сказал с низким поклоном: «Спасибо, ваше благородие! Награди вас господь за вашу добродетель. Век не забуду ваших милостей»."}], "games": [{"type": "choice", "label": "Чья реплика", "q": "Кто сказал эти слова?", "quote": "«Он его пропьёт, собака, в первом кабаке»", "opts": ["Ямщик", "Савельич", "Вожатый", "Пётр"], "a": 1, "para": 1, "ex": "Так ворчал Савельич, которому было жалко барского тулупа."}, {"type": "error", "label": "Найди ошибку", "q": "В пересказ вкралось одно неверное слово. Нажми на него.", "words": ["Тулуп", "был", "немножко", "для", "него", "широк,", "и", "он", "надел", "его,", "распоров", "по", "швам"], "a": 5, "para": 3, "ex": "Тулуп был ему узок, поэтому бродяга и распорол его по швам."}, {"type": "choice", "label": "Детали", "q": "Что пообещал вожатый на прощание?", "opts": ["Вернуть тулуп весной", "Век не забыть милостей Петра", "Проводить до Оренбурга", "Написать отцу Петра"], "a": 1, "para": 4, "ex": "«Век не забуду ваших милостей». Запомни эти слова: они ещё прозвучат в книге."}]}, "l6": {"paras": [{"note": "В Оренбурге генерал отправил Петра служить в Белогорскую крепость, под начало капитана Миронова."}, {"t": "«Далече ли до крепости?» — спросил я у своего ямщика. «Недалече, — отвечал он. — Вон уж видна». Я глядел во все стороны, ожидая увидеть грозные [[бастионы|bast]], башни и вал; но ничего не видал, кроме деревушки, окружённой бревенчатым забором."}, {"t": "С одной стороны стояли три или четыре [[скирда|skird]] сена, полузанесённые снегом; с другой скривившаяся мельница, с [[лубочными|lub]] крыльями, лениво опущенными."}], "games": [{"type": "choice", "label": "Ожидание и правда", "q": "Что ожидал увидеть Пётр?", "opts": ["Грозные бастионы, башни и вал", "Большой город", "Казачий лагерь", "Деревянную церковь"], "a": 0, "para": 1, "ex": "Он ждал настоящую крепость, а увидел деревушку за забором."}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово.", "words": ["Ничего", "не", "видал,", "кроме", "деревушки,", "окружённой", "каменным", "забором"], "a": 6, "para": 1, "ex": "Деревушка была окружена бревенчатым забором, а не каменным."}, {"type": "choice", "label": "Детали", "q": "Какой была мельница у крепости?", "opts": ["Новой, с яркими крыльями", "Скривившейся, с лениво опущенными крыльями", "Каменной водяной", "Сгоревшей"], "a": 1, "para": 2, "ex": "Скривившаяся мельница с лубочными крыльями, лениво опущенными."}]}, "l7": {"paras": [{"note": "В день приезда Пётр познакомился с Василисой Егоровной, женой коменданта. Она сразу рассказала про одного офицера."}, {"t": "«Швабрин Алексей Иваныч вот уж пятый год как к нам переведён за смертоубийство. Бог знает, какой грех его попутал; он, изволишь видеть, поехал за город с одним поручиком, да взяли с собою шпаги, да и ну друг в друга пырять; а Алексей Иваныч и заколол поручика, да ещё при двух свидетелях!»"}, {"note": "Прошла ночь."}, {"t": "На другой день поутру я только что стал одеваться, как дверь отворилась, и ко мне вошёл молодой офицер невысокого роста, с лицом смуглым и отменно некрасивым, но чрезвычайно живым."}, {"note": "В тот же день Петра позвали обедать к коменданту."}, {"t": "Тут вошла девушка лет осьмнадцати, круглолицая, румяная, с светло-русыми волосами, гладко зачёсанными за уши, которые у ней так и горели."}], "games": [{"type": "choice", "label": "Чей портрет", "q": "О ком сказано: «с лицом смуглым и отменно некрасивым, но чрезвычайно живым»?", "opts": ["О Швабрине", "О капитане Миронове", "О вожатом", "О Савельиче"], "a": 0, "para": 3, "ex": "Так Пётр описывает Швабрина при первой встрече."}, {"type": "choice", "label": "Прошлое героя", "q": "За что Швабрина перевели в крепость?", "opts": ["За карточные долги", "За поединок, в котором он заколол поручика", "За побег со службы", "За дерзость генералу"], "a": 1, "para": 1, "ex": "Василиса Егоровна рассказывает, что Швабрин заколол поручика на поединке."}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово в портрете Маши.", "words": ["Девушка", "лет", "осьмнадцати,", "круглолицая,", "бледная,", "с", "светло-русыми", "волосами"], "a": 4, "para": 5, "ex": "Маша была румяной, а не бледной."}]}, "l8": {"paras": [{"note": "Швабрин посмеялся над песенкой, которую Пётр сочинил для Маши, и грубо отозвался о ней самой. Пётр вызвал его на поединок. Противники сошлись на берегу реки."}, {"t": "Вдруг услышал я своё имя, громко произнесённое. Я оглянулся и увидел Савельича, сбегающего ко мне по нагорной тропинке… В это самое время меня сильно кольнуло в грудь пониже правого плеча; я упал и лишился чувств."}], "games": [{"type": "hero", "label": "Выбор героя", "q": "Швабрин смеётся над твоими стихами и оскорбляет девушку. Как поступишь?", "opts": ["Вызвать его на поединок", "Пожаловаться коменданту", "Промолчать и уйти"], "reveal": "Пётр вызвал Швабрина. Честь смолоду, как велел отец, но в поединке его отвлёк крик Савельича."}, {"type": "order", "label": "Хронология", "q": "Восстанови ход событий.", "items": ["Швабрин смеётся над песенкой Петра", "Пётр вызывает его на поединок", "Противники сходятся у реки", "Пётр оглядывается на крик Савельича", "Швабрин ранит Петра"], "para": 1, "ex": "Миг, когда Пётр оглянулся на Савельича, и решил исход поединка."}, {"type": "choice", "label": "Детали", "q": "Куда был ранен Пётр?", "opts": ["В руку", "В грудь пониже правого плеча", "В ногу", "В голову"], "a": 1, "para": 1, "ex": "«Меня сильно кольнуло в грудь пониже правого плеча»."}]}, "l9": {"paras": [{"note": "Пётр поправился после раны. Всё это время за ним ухаживала Маша. Он признался ей в любви."}, {"t": "Она безо всякого [[жеманства|zheman]] призналась мне в сердечной склонности и сказала, что её родители, конечно, рады будут её счастию."}, {"note": "Пётр написал отцу и попросил благословения. Ответ пришёл суровый."}, {"t": "«Не только ни моего благословения, ни моего согласия дать я тебе не намерен, но еще и собираюсь до тебя добраться да за проказы твои проучить тебя путем как мальчишку, несмотря на твой офицерской чин…»"}, {"t": "«Немедленно буду писать к Андрею Карловичу, прося его перевести тебя из Белогорской крепости куда-нибудь подальше, где бы дурь у тебя прошла»."}, {"note": "Пётр показал письмо Маше."}, {"t": "«Видно, мне не судьба… Родные ваши не хотят меня в свою семью»."}, {"t": "«Я не выйду за тебя без благословения твоих родителей»."}], "games": [{"type": "choice", "label": "Письмо отца", "q": "Куда отец собирается просить перевести сына?", "opts": ["Из Белогорской крепости куда-нибудь подальше", "В Петербург, в гвардию", "Домой, в Симбирскую деревню", "В Оренбург, к генералу"], "a": 0, "para": 4, "ex": "«…куда-нибудь подальше, где бы дурь у тебя прошла»."}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово в словах Маши.", "words": ["Я", "не", "выйду", "за", "тебя", "без", "благословения", "моих", "родителей."], "a": 7, "para": 7, "ex": "Маша говорит «твоих родителей»: ей нужно благословение отца и матери Петра."}, {"type": "choice", "label": "Детали", "q": "Как отец грозится проучить сына?", "opts": ["Как мальчишку, несмотря на офицерский чин", "Лишить его наследства", "Записать в солдаты", "Не пускать домой"], "a": 0, "para": 3, "ex": "«…проучить тебя путем как мальчишку, несмотря на твой офицерской чин»"}]}, "l10": {"paras": [{"note": "Комендант получил от генерала секретное письмо."}, {"t": "«…убежавший из-под [[караула|karaul]] донской казак и [[раскольник|raskol]] Емельян Пугачев, учиня непростительную дерзость принятием на себя имени покойного императора Петра III…»"}, {"t": "«А пуще всего содержите все это в тайне, чтоб в крепости никто не мог о том узнать преждевременно»."}, {"note": "Но тайна скоро разошлась по крепости. Поймали башкирца, который вёз письма бунтовщиков."}, {"t": "Никогда не забуду этого человека. Ему казалось лет за семьдесят. У него не было ни носа, ни ушей."}, {"note": "Машу решили отправить в Оренбург, подальше от опасности."}, {"t": "«Прощайте, Петр Андреич! — сказала она мне со слезами. — Меня посылают в Оренбург»."}], "games": [{"type": "choice", "label": "Самозванец", "q": "Чьё имя присвоил себе Пугачёв?", "opts": ["Покойного императора Петра III", "Оренбургского генерала", "Коменданта Миронова", "Донского атамана"], "a": 0, "para": 1, "ex": "«…принятием на себя имени покойного императора Петра III»."}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово в строке из письма.", "words": ["убежавший", "из-под", "караула", "уральский", "казак", "и", "раскольник", "Емельян", "Пугачев"], "a": 3, "para": 1, "ex": "В письме сказано: «донской казак»."}, {"type": "choice", "label": "Приказ", "q": "Что генерал велел сделать с известием?", "opts": ["Хранить в тайне", "Объявить всему гарнизону", "Переслать в Петербург", "Сжечь письмо"], "a": 0, "para": 2, "ex": "«А пуще всего содержите все это в тайне»."}]}, "l11": {"paras": [{"note": "Маша не успела уехать: дорога в Оренбург была отрезана, крепость окружена. Мятежники пошли на приступ."}, {"t": "«Ну, детушки, постоим сегодня за матушку государыню и докажем всему свету, что мы люди бравые и [[присяжные|prisyazh]]!»"}, {"note": "Мятежники ворвались в крепость. Раненого коменданта привели к Пугачёву и потребовали присяги."}, {"t": "«Ты мне не государь, ты вор и [[самозванец|samozv]], слышь ты!»"}, {"note": "Комендант не изменил присяге и погиб. Старый поручик тоже отказался присягнуть."}, {"t": "«Ты нам не государь», — отвечал Иван Игнатьич, повторяя слова своего капитана."}], "games": [{"type": "order", "label": "Хронология", "q": "Восстанови ход событий.", "items": ["Комендант ободряет гарнизон: «Ну, детушки…»", "Мятежники врываются в крепость", "Комендант называет Пугачёва вором и самозванцем", "Иван Игнатьич повторяет слова капитана"], "para": 1, "ex": "Комендант и его поручик остались верны присяге до конца."}, {"type": "choice", "label": "Чья реплика", "q": "Кто сказал эти слова?", "quote": "«Ну, детушки, постоим сегодня за матушку государыню…»", "opts": ["Комендант Миронов", "Пугачёв", "Швабрин", "Иван Игнатьич"], "a": 0, "para": 1, "ex": "Так комендант обращается к гарнизону перед приступом."}, {"type": "hero", "label": "Выбор героя", "q": "Тебя приводят к самозванцу и требуют присяги. Как поступишь?", "opts": ["Отказаться, как комендант", "Присягнуть, чтобы спастись", "Промолчать"], "reveal": "Пётр, как и его командиры, решил не изменять присяге. Это едва не стоило ему жизни."}]}, "l12": {"paras": [{"note": "Самозванец сидел в креслах на крыльце комендантского дома."}, {"t": "На нём был красный казацкий кафтан, обшитый [[галунами|galun]]."}, {"t": "Лицо его показалось мне знакомо."}, {"note": "Петра повели на казнь. Вдруг Савельич бросился в ноги Пугачёву."}, {"t": "«Отец родной! — говорил бедный дядька. — Что тебе в смерти барского дитяти?»"}, {"t": "Пугачев дал знак, и меня тотчас развязали и оставили."}, {"note": "Петру велели поцеловать руку самозванцу."}, {"t": "«Батюшка Петр Андреич! — шептал Савельич, стоя за мною и толкая меня. — Не упрямься! что тебе стоит? плюнь да поцелуй у злод… (тьфу!) поцелуй у него ручку»."}, {"t": "Но я предпочел бы самую лютую казнь такому подлому унижению."}], "games": [{"type": "choice", "label": "Детали", "q": "Как был одет самозванец?", "opts": ["В красный казацкий кафтан, обшитый галунами", "В заячий тулуп", "В генеральский мундир", "В оборванный армяк"], "a": 0, "para": 1, "ex": "«На нём был красный казацкий кафтан, обшитый галунами»."}, {"type": "choice", "label": "Спаситель", "q": "Кто спас Петра от казни?", "opts": ["Савельич", "Маша", "Швабрин", "Иван Игнатьич"], "a": 0, "para": 4, "ex": "Савельич бросился в ноги Пугачёву: «Отец родной!..»"}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово.", "words": ["Но", "я", "предпочел", "бы", "самую", "лёгкую", "казнь", "такому", "подлому", "унижению."], "a": 5, "para": 8, "ex": "«Самую лютую казнь»: Пётр не готов на унижение даже ради жизни."}]}, "l13": {"paras": [{"t": "Неизвестность о судьбе Марьи Ивановны пуще всего меня мучила."}, {"note": "Пётр поспешил к дому священника."}, {"t": "«Барышня жива, — отвечала Палаша. — Она спрятана у Акулины Памфиловны»."}, {"note": "Вернувшись домой, Пётр услышал от Савельича неожиданное."}, {"t": "«Ты и позабыл того пьяницу, который выманил у тебя тулуп на постоялом дворе?»"}, {"note": "Самозванец оказался тем самым вожатым, которому Пётр подарил заячий тулуп."}], "games": [{"type": "choice", "label": "Где Маша", "q": "У кого спрятана Маша?", "opts": ["У Акулины Памфиловны", "У Палаши", "У Швабрина", "У Савельича"], "a": 0, "para": 2, "ex": "«Она спрятана у Акулины Памфиловны»."}, {"type": "choice", "label": "Узнавание", "q": "Кем оказался самозванец?", "opts": ["Вожатым с постоялого двора", "Ямщиком", "Беглым солдатом из Оренбурга", "Братом Швабрина"], "a": 0, "para": 4, "ex": "Это «тот пьяница», который «выманил» у Петра тулуп."}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово в словах Савельича.", "words": ["Ты", "и", "позабыл", "того", "пьяницу,", "который", "выманил", "у", "тебя", "шубу", "на", "постоялом", "дворе?"], "a": 9, "para": 4, "ex": "Савельич говорит про тулуп — тот самый заячий тулуп из второго акта."}]}, "l14": {"paras": [{"note": "Пугачёв позвал Петра к себе."}, {"t": "«Ты крепко передо мною виноват, — продолжал он, — но я помиловал тебя за твою добродетель, за то, что ты оказал мне услугу, когда принужден я был скрываться от своих [[недругов|nedrug]]»."}, {"t": "«Послужи мне верой и правдою, и я тебя пожалую и в фельдмаршалы и в князья»."}, {"t": "«Я природный дворянин; я присягал государыне императрице: тебе служить не могу»."}, {"note": "Пугачёв стал допытываться, будет ли Пётр воевать против него."}, {"t": "«Голова моя в твоей власти: отпустишь меня — спасибо; казнишь — бог тебе судья; а я сказал тебе правду»."}, {"t": "«Так и быть, — сказал он, ударя меня по плечу. — Казнить так казнить, миловать так миловать»."}, {"t": "«Ступай себе на все четыре стороны и делай что хочешь»."}], "games": [{"type": "choice", "label": "Чья реплика", "q": "Кто сказал эти слова?", "quote": "«Послужи мне верой и правдою, и я тебя пожалую и в фельдмаршалы и в князья»", "opts": ["Пугачёв", "Генерал", "Швабрин", "Отец Петра"], "a": 0, "para": 2, "ex": "Так самозванец уговаривает Петра перейти к нему на службу."}, {"type": "hero", "label": "Выбор героя", "q": "Самозванец предлагает службу и чины. Твой ответ?", "opts": ["Отказаться: я присягал", "Согласиться ради Маши", "Схитрить и пообещать"], "reveal": "Пётр ответил честно: «Я природный дворянин; я присягал государыне императрице: тебе служить не могу». Эта прямота поразила Пугачёва."}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово.", "words": ["Казнить", "так", "казнить,", "миловать", "так", "прощать."], "a": 5, "para": 6, "ex": "В книге: «Казнить так казнить, миловать так миловать»."}]}, "l15": {"paras": [{"note": "Утром самозванец уезжал из крепости и объявил народу:"}, {"t": "«Вот вам, детушки, новый командир: слушайтесь его во всем, а он отвечает мне за вас и за крепость»."}, {"note": "Новым командиром Пугачёв поставил Швабрина."}, {"t": "В это время из толпы народа, вижу, выступил мой Савельич, подходит к Пугачеву и подает ему лист бумаги."}, {"t": "«Как ты смел лезть ко мне с такими пустяками? — вскричал он, выхватя бумагу из рук секретаря и бросив ее в лицо Савельичу»."}, {"t": "Ночью у Марьи Ивановны открылась сильная горячка. Она лежала без памяти и в бреду."}, {"note": "Пётр пришёл проститься с Машей."}, {"t": "Я взял руку бедной девушки и поцеловал ее, орошая слезами."}, {"note": "Пётр с Савельичем отправились в Оренбург. В пути их догнал [[урядник|uryad]]."}, {"t": "«Ваше благородие! Отец наш вам жалует лошадь и шубу с своего плеча»."}], "games": [{"type": "choice", "label": "Новый командир", "q": "Кого Пугачёв оставил командиром крепости?", "opts": ["Швабрина", "Ивана Игнатьича", "Савельича", "Максимыча"], "a": 0, "para": 1, "ex": "Командиром Белогорской крепости стал Швабрин — а значит, Маша в его власти."}, {"type": "order", "label": "Хронология", "q": "Восстанови ход событий.", "items": ["Пугачёв объявляет нового командира", "Савельич подаёт Пугачёву лист бумаги", "Пугачёв бросает бумагу в лицо Савельичу", "Пётр прощается с Машей", "Урядник привозит лошадь и шубу"], "para": 1, "ex": "Самозванец рассердился на Савельича, но потом всё же прислал Петру подарок в дорогу."}, {"type": "choice", "label": "Детали", "q": "Что прислал Пугачёв Петру в дорогу?", "opts": ["Лошадь и шубу с своего плеча", "Шпагу коменданта", "Охранную грамоту", "Мешок денег"], "a": 0, "para": 9, "ex": "«Отец наш вам жалует лошадь и шубу с своего плеча»."}]}, "l16": {"paras": [{"note": "В Оренбурге генерал собрал военный совет. Пётр высказался за то, чтобы выступить против мятежников."}, {"t": "Я встал и, в коротких словах описав сперва Пугачева и шайку его, сказал утвердительно, что самозванцу способа не было устоять противу правильного оружия."}, {"note": "Но генерал решил иначе."}, {"t": "«Я соглашаюсь с большинством голосов, которое решило, что всего благоразумнее и безопаснее внутри города ожидать осады…»"}, {"t": "Скажу вкратце, что сия осада по неосторожности местного начальства была гибельна для жителей, которые претерпели голод и всевозможные бедствия."}, {"note": "Однажды к Петру подъехал урядник Максимыч из Белогорской крепости."}, {"t": "Тут он подал мне сложенную бумажку и тотчас ускакал."}, {"note": "Это было письмо от Маши."}, {"t": "«Алексей Иванович принуждает меня выйти за него замуж. Он говорит, что спас мне жизнь…»"}, {"note": "Пётр бросился к генералу просить солдат."}, {"t": "«Эта экспедиция была бы неблагоразумна; я не могу взять ее на свою ответственность»."}], "games": [{"type": "choice", "label": "Совет", "q": "Что предлагал Пётр на военном совете?", "opts": ["Выступить: самозванцу не устоять против правильного оружия", "Ждать осады внутри города", "Вести переговоры с Пугачёвым", "Отступить из Оренбурга"], "a": 0, "para": 1, "ex": "Пётр был за решительные действия, но совет решил иначе."}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово в письме Маши.", "words": ["Алексей", "Иванович", "принуждает", "меня", "выйти", "за", "него", "замуж.", "Он", "говорит,", "что", "спас", "мне", "честь."], "a": 13, "para": 8, "ex": "В письме: «Он говорит, что спас мне жизнь»."}, {"type": "choice", "label": "Отказ", "q": "Что ответил генерал на просьбу дать солдат?", "opts": ["Экспедиция была бы неблагоразумна", "Дал роту солдат", "Велел ждать весны", "Сам повёл войско"], "a": 0, "para": 10, "ex": "«Эта экспедиция была бы неблагоразумна; я не могу взять ее на свою ответственность»."}]}, "l17": {"paras": [{"note": "Пётр с Савельичем поехали выручать Машу. У Бердской [[слободы|sloboda]], где стоял Пугачёв, их схватили мятежники."}, {"t": "Один из них, по-видимому главный, объявил нам, что он сейчас поведет нас к государю."}, {"note": "Пётр рассказал самозванцу, что Швабрин держит в неволе девушку и насильно хочет на ней жениться."}, {"t": "«Кто из моих людей смеет обижать сироту? — закричал он»."}, {"note": "По дороге в крепость Пугачёв рассказал Петру сказку, которую в детстве слышал от старой калмычки."}, {"t": "«Однажды орел спрашивал у ворона: скажи, ворон-птица, отчего живешь ты на белом свете триста лет, а я всего-навсе только тридцать три года?»"}, {"note": "Орёл попробовал питаться падалью, как ворон, и сказал:"}, {"t": "«…чем триста лет питаться падалью, лучше раз напиться живой кровью, а там что бог даст!»"}, {"t": "«Но жить убийством и разбоем значит по мне клевать мертвечину»."}], "games": [{"type": "choice", "label": "Сказка", "q": "Сколько лет живёт ворон в сказке?", "opts": ["Триста", "Тридцать три", "Сто", "Семьдесят"], "a": 0, "para": 5, "ex": "Ворон живёт триста лет, а орёл — всего тридцать три года."}, {"type": "hero", "label": "Выбор героя", "q": "Самозванец спрашивает, как тебе его сказка. Что ответишь?", "opts": ["Скажу честно, что думаю", "Похвалю, чтобы не злить", "Промолчу"], "reveal": "Пётр ответил прямо: «Но жить убийством и разбоем значит по мне клевать мертвечину». И Пугачёв не разгневался."}, {"type": "choice", "label": "Мораль", "q": "Как Пётр ответил на сказку?", "opts": ["Жить убийством и разбоем — значит клевать мертвечину", "Орёл прав: лучше раз напиться живой крови", "Ворон мудрее орла", "Сказка ему понравилась"], "a": 0, "para": 8, "ex": "Пётр не согласился с «моралью» орла."}]}, "l18": {"paras": [{"note": "Швабрин нехотя отпер дверь светлицы."}, {"t": "На полу, в крестьянском оборванном платье сидела Марья Ивановна, бледная, худая, с растрепанными волосами."}, {"t": "«Я никогда не буду его женою! Я лучше решилась умереть, и умру, если меня не избавят»."}, {"t": "«Выходи, красная девица; дарую тебе волю. Я государь»."}, {"t": "Марья Ивановна быстро взглянула на него и догадалась, что перед нею убийца ее родителей."}, {"t": "«Возьми себе свою красавицу; вези ее куда хочешь, и дай вам бог любовь да совет!»"}], "games": [{"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово.", "words": ["На", "полу,", "в", "крестьянском", "новом", "платье", "сидела", "Марья", "Ивановна,", "бледная,", "худая"], "a": 4, "para": 1, "ex": "Маша была в «крестьянском оборванном платье»."}, {"type": "choice", "label": "Решение", "q": "Что сказал Пугачёв Маше?", "opts": ["«Выходи, красная девица; дарую тебе волю»", "«Выходи замуж за Швабрина»", "«Поедешь со мной в Бердскую слободу»", "«Оставайся в крепости»"], "a": 0, "para": 3, "ex": "Самозванец отпустил Машу и отдал её Петру."}, {"type": "choice", "label": "Догадка", "q": "О чём догадалась Маша, взглянув на Пугачёва?", "opts": ["Что перед ней убийца её родителей", "Что он вожатый Петра", "Что он настоящий государь", "Что он отпустит Швабрина"], "a": 0, "para": 4, "ex": "Маша поняла, кто перед ней, и лишилась чувств."}]}, "l19": {"paras": [{"note": "По дороге Пётр с Машей наткнулись на гусарский отряд."}, {"t": "Каково было мое изумление, когда, взглянув на него, узнал я Ивана Ивановича Зурина, некогда обыгравшего меня в Симбирском трактире!"}, {"t": "«Отправь ее завтра ж одну к родителям твоим; а сам оставайся у меня в отряде»."}, {"note": "Маша с Савельичем уехала к родителям Петра, а Пётр остался воевать в отряде Зурина."}, {"t": "Война была кончена."}, {"t": "Я стал ее читать: это был секретный приказ ко всем отдельным начальникам арестовать меня, где бы ни попался, и немедленно отправить под караулом в Казань в Следственную комиссию, учрежденную по делу Пугачева."}], "games": [{"type": "choice", "label": "Встреча", "q": "Кого Пётр узнал в командире отряда?", "opts": ["Зурина", "Швабрина", "Генерала", "Максимыча"], "a": 0, "para": 1, "ex": "Зурин когда-то обыграл Петра на бильярде в Симбирском трактире — это было ещё в начале повести."}, {"type": "choice", "label": "Совет друга", "q": "Что посоветовал Зурин?", "opts": ["Отправить Машу к родителям Петра, а самому остаться в отряде", "Обвенчаться немедленно", "Ехать в Петербург", "Вернуться в Оренбург"], "a": 0, "para": 2, "ex": "«Отправь ее завтра ж одну к родителям твоим; а сам оставайся у меня в отряде»."}, {"type": "error", "label": "Найди ошибку", "q": "Нажми на неверное слово в приказе.", "words": ["немедленно", "отправить", "под", "караулом", "в", "Оренбург", "в", "Следственную", "комиссию"], "a": 5, "para": 5, "ex": "Петра велено отправить в Казань."}]}, "l20": {"paras": [{"note": "На следствии Петра обвинили в измене. Против него показал схваченный Швабрин."}, {"t": "Мне пришло в голову, что если назову ее, то комиссия потребует ее к ответу."}, {"note": "Пётр не стал оправдываться, чтобы не впутывать Машу."}, {"t": "Государыня, из уважения к заслугам и преклонным летам отца, решилась помиловать преступного сына и, избавляя его от позорной казни, повелела только сослать в отдаленный край Сибири на вечное поселение."}, {"note": "Тогда Маша решилась ехать в Петербург сама. В саду Царского Села она встретила незнакомую даму."}, {"t": "Она была в белом утреннем платье, в ночном чепце и в [[душегрейке|dushegr]]."}, {"t": "«Я приехала просить милости, а не правосудия»."}, {"note": "Дама оказалась самой императрицей. Петра помиловали."}, {"t": "Он был освобожден от заключения в конце 1774 года, по именному повелению."}, {"t": "Пугачев узнал его в толпе и кивнул ему головою…"}], "games": [{"type": "choice", "label": "Молчание", "q": "Почему Пётр не назвал на суде имя Маши?", "opts": ["Боялся, что комиссия потребует её к ответу", "Забыл о ней", "Они поссорились", "Его не спрашивали"], "a": 0, "para": 1, "ex": "Пётр берёг Машу и промолчал, хотя мог оправдаться."}, {"type": "order", "label": "Хронология", "q": "Восстанови ход событий.", "items": ["Петра приговаривают к поселению в Сибири", "Маша встречает даму в саду Царского Села", "Маша просит милости, а не правосудия", "Пётр освобождён по именному повелению"], "para": 3, "ex": "Маша спасла Петра так же, как когда-то он спас её."}, {"type": "choice", "label": "Просьба", "q": "Чего Маша просила у государыни?", "opts": ["Милости, а не правосудия", "Наказания Швабрина", "Денег на свадьбу", "Места при дворе"], "a": 0, "para": 6, "ex": "«Я приехала просить милости, а не правосудия»."}]}});
